DELIMITER $$
--
-- Évènements
--
CREATE DEFINER=`Marais_R_Site_User`@`%` EVENT `archiver_mesures_mensuelles` ON SCHEDULE EVERY 1 MONTH STARTS '2026-01-01 01:00:00' ON COMPLETION NOT PRESERVE ENABLE DO BEGIN
    SELECT 
        DATE(`date_heure_mesure`) as jour, 
        `id_emplacement`,
        `id_type_mesure`, 
        AVG(`valeur_mesure`),
        MAX(`valeur_mesure`),
        MIN(`valeur_mesure`),
        COUNT(*)
    FROM `mesure`
    WHERE `date_heure_mesure` < DATE_FORMAT(NOW() ,'%Y-%m-01')
    GROUP BY jour, `id_emplacement`, `id_type_mesure`;
 
    DELETE FROM `type_info_mesure_as_mesure` 
    WHERE `id_mesure` IN (
        SELECT `id_mesure` FROM `mesure` 
        WHERE `date_heure_mesure` < DATE_FORMAT(NOW() ,'%Y-%m-01')
    );
 
    DELETE FROM `mesure` 
    WHERE `date_heure_mesure` < DATE_FORMAT(NOW() ,'%Y-%m-01');
END$$

DELIMITER ;
